package com.notificationservice.infrastructure.persistence.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="support_messages")
public class SupportMessageEntity { @Id private UUID id; @Column(name="conversation_id",nullable=false) private UUID conversationId; @Column(name="sender_id",nullable=false) private UUID senderId; @Column(name="sender_role",nullable=false,length=32) private String senderRole; @Column(columnDefinition="TEXT") private String content; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="edited_at") private Instant editedAt; @Column(name="read_at") private Instant readAt;
 public UUID getId(){return id;} public void setId(UUID v){id=v;} public UUID getConversationId(){return conversationId;} public void setConversationId(UUID v){conversationId=v;} public UUID getSenderId(){return senderId;} public void setSenderId(UUID v){senderId=v;} public String getSenderRole(){return senderRole;} public void setSenderRole(String v){senderRole=v;} public String getContent(){return content;} public void setContent(String v){content=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getEditedAt(){return editedAt;} public void setEditedAt(Instant v){editedAt=v;} public Instant getReadAt(){return readAt;} public void setReadAt(Instant v){readAt=v;}}
